#!/bin/bash
# Runs the equivalence lemma against each generated mutant through the lock script (gate options plus
# --filter-symbol MutantIffFlat, so only that lemma is verified). Log per mutant: logs/mut-<name>-NN.log
E=<REPO>/results/night-shift-20261119/orch-B/b-export-bridge
T=<REPO>/results/night-shift-20261119/orch-B/tools/dafny_locked.sh
Z=<REPO>/.toolchain/dafny-4.11.0/dafny/z3/bin/z3-4.12.1
for n in "$@"; do
  cat > $E/mutants/Check-$n.dfy <<EOD
// b-export-bridge mutant harness (generated by run_mutants.sh). Must FAIL unless the mutant is semantically neutral.
include "$n.dfy"
module MutantCheck {
  import opened SliceTheorem
  import L = LinkedRefund
  import opened ExportedGen
  lemma MutantIffFlat(x: FlatIn, o: L.FlatTuple)
    ensures ExportedContract(x, o) <==> FlatContract(x, o)
  {
  }
}
EOD
  k=1; while [ -e $E/logs/mut-$n-0$k.log ]; do k=$((k+1)); done
  LOG=$E/logs/mut-$n-0$k.log
  bash $T b-export-bridge $E/mutants $LOG 90 verify --solver-path $Z --resource-limit 1000000 --verification-time-limit 0 --cores 1 --verify-included-files --track-print-effects --filter-symbol MutantIffFlat Check-$n.dfy >/dev/null 2>&1
  echo "$n $(tail -1 $LOG) | $(grep -m1 'verifier finished' $LOG) | $(grep -m1 -o 'Error: [^.]*' $LOG)"
done
